// Uploads the built artifact to the release bucket.
const fs = require("fs");

// Release bucket name is not recorded in this repo; it is supplied via the
// RELEASE_BUCKET environment variable (fill in a literal here instead if
// you prefer to hardcode it).
const BUCKET = process.env.RELEASE_BUCKET || "";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set (provide RELEASE_BUCKET)");
  }
  const res = await fetch(
    `https://storage.googleapis.com/${BUCKET}/${name}`,
    { method: "PUT", body }
  );
  if (!res.ok) {
    throw new Error(
      `upload failed: ${res.status} ${res.statusText} (bucket ${BUCKET}, object ${name})`
    );
  }
  console.log(`uploaded ${name} (${body.length} bytes)`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

